import{z as i,x as l,o as n,c as s,q as e,j as t,D as E,d as o,s as B,S as A}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"Lagrange 插值","description":"","frontmatter":{"title":"Lagrange 插值","date":"2026-09-27T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/lagrange-interpolation.md","filePath":"cs/lagrange-interpolation.md","lastUpdated":1791063341000}'),p={name:"cs/lagrange-interpolation.md"};function d(_,a,g,C,c,m){const r=l("Mermaid");return n(),s("div",null,[a[2]||(a[2]=e('<h1 id="lagrange-插值" tabindex="-1">Lagrange 插值 <a class="header-anchor" href="#lagrange-插值" aria-label="Permalink to &quot;Lagrange 插值&quot;">​</a></h1><div class="epigraph"><p>过 $n+1$ 个横坐标互异的点，恰有一个次数至多 $n$ 的多项式——求值容易，插值回去也该有便宜的路。</p><footer>—— J.-L. Lagrange, 1795 师范学校讲义；插值公式的经典出处</footer></div><p><a href="/cs/matrix-tree-theorem">上一课</a>用行列式把「数树」压成一次消元；这一课做反向的事：把散落的点值升回系数。缺口是 <strong>Lagrange 插值</strong>：多项式的系数表示与点值表示一一对应，插值就是换一套坐标基。本课写朴素公式与 \\(O(n)\\) 的前后缀变体，不写数值稳定性分析与样条。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>系数侧加法便宜、乘法要卷积；点值侧乘法逐点相乘、加法要插值——两套表示各持半张牌。竞赛里的典型缺口：\\(\\sum_{i=0}^{n-1} i^k\\) 这类在等距点上取值的量，本质是一个次数 \\(k+1\\) 的多项式，取 \\(k+2\\) 个点插回去就绕开了逐项求和。本课不写 <a href="/cs/fft">FFT</a> 的推导，只认它「系数与点值互转」这个身份。</p><p><span class="marginnote">术语翻译：interpolation 插值 = 已知点值求系数；interpolation nodes 插值节点 = 那组横坐标 \\(x_i\\)；\\(n+1\\) 个点确定的是次数至多 \\(n\\) 的多项式，次数上界比点数少一。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对每个 \\(i\\) 造基函数 \\(L_i\\)：在 \\(x_i\\) 处取 \\(1\\)、在其余节点取 \\(0\\)，答案即 \\(\\sum_i y_i L_i(x)\\)。分子连乘 \\(\\prod_{j\\ne i}(x-x_j)\\)，分母除掉 \\(x_i-x_j\\)；节点取 \\(0\\) 到 \\(n\\) 这类规律点时，分子分母的前后缀连乘让单点求值 \\(O(n)\\)；任意节点则要付分治乘法的账。</p>',8)),(n(),t(A,null,{default:E(()=>[B(r,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E8%BE%93%E5%85%A5%20n%20%E5%8A%A0%201%20%E4%B8%AA%E7%82%B9%E5%80%BC%22%5D%20--%3E%20B%7B%22%E8%8A%82%E7%82%B9%E6%A8%AA%E5%9D%90%E6%A0%87%E4%BA%92%E5%BC%82%E5%90%97%22%7D%0A%20%20B%20--%3E%7C%22%E5%90%A6%22%7C%20E%5B%22%E5%88%86%E6%AF%8D%E5%87%BA%E7%8E%B0%200%EF%BC%9A%E6%8F%92%E5%80%BC%E6%97%A0%E5%AE%9A%E4%B9%89%22%5D%0A%20%20B%20--%3E%7C%22%E6%98%AF%22%7C%20C%5B%22%E8%BF%9E%E4%B9%98%E5%88%86%E5%AD%90%E5%88%86%E6%AF%8D%E7%9A%84%E5%89%8D%E5%90%8E%E7%BC%80%E7%A7%AF%22%5D%0A%20%20C%20--%3E%20D%5B%22%E9%80%90%E9%A1%B9%E7%BB%84%E5%90%88%E5%87%BA%E6%AF%8F%E4%B8%AA%E5%9F%BA%E5%87%BD%E6%95%B0%E7%9A%84%E5%80%BC%22%5D%0A%20%20D%20--%3E%20F%5B%22%E6%8C%89%20y_i%20%E5%8A%A0%E6%9D%83%E6%B1%82%E5%92%8C%22%5D%0A%20%20F%20--%3E%20G%5B%22%E8%BE%93%E5%87%BA%E6%AC%A1%E6%95%B0%E8%87%B3%E5%A4%9A%20n%20%E7%9A%84%E5%A4%9A%E9%A1%B9%E5%BC%8F%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e('<p><span class="marginnote">数字实例：过 \\((0,0),(1,1),(2,4)\\) 三点，答案是 \\(x^2\\)。取 \\(x=3\\) 验基函数：\\(L_0(3)=\\frac{(3-1)(3-2)}{(0-1)(0-2)}=1\\)，\\(L_1(3)=\\frac{(3-0)(3-2)}{(1-0)(1-2)}=-3\\)，\\(L_2(3)=\\frac{(3-0)(3-1)}{(2-0)(2-1)}=3\\)；加权 \\(0\\cdot1+1\\cdot(-3)+4\\cdot3=9=3^2\\)，三点钉死抛物线。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>唯一性是地基：若两个次数至多 \\(n\\) 的多项式在 \\(n+1\\) 个互异点上同值，其差有 \\(n+1\\) 个根，而非零多项式根数不超过次数，故差恒为零。同一件事的另一面：插值是解 Vandermonde 线性方程组，Lagrange 公式只是把这个矩阵的逆写成了显式。节点取得「顺手」（等距、单位根）时变换便宜，任意节点则要付分治乘法的账。</p><p><span class="marginnote">直觉类比：系数与点值是同一支箭的两套坐标，像直角坐标与极坐标之于同一个向量。Lagrange 插值就是坐标变换矩阵的显式逆——<a href="/cs/fft">FFT</a> 是等距节点下最快的摆渡船，任意节点时船票按 \\(O(n\\log^2 n)\\) 计价。</span></p><p><span class="marginnote">常见误区：以为节点必须等距或必须取 \\(0\\) 到 \\(n\\)。互异即可——等距只是让分子分母的连乘有规律、前后缀积能 \\(O(n)\\) 处理；硬把非等距点塞进前后缀套路会算出错误系数，错在假设了不存在的等差结构。</span></p>',5)),(n(),t(A,null,{default:E(()=>[B(r,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%7B%22%E8%A6%81%E5%93%AA%E4%B8%80%E4%BE%A7%E7%9A%84%E8%A1%A8%E7%A4%BA%22%7D%20--%3E%20C%5B%22%E7%B3%BB%E6%95%B0%E4%BE%A7%EF%BC%9A%E5%8A%A0%E6%B3%95%E4%BE%BF%E5%AE%9C%E3%80%81%E4%B9%98%E6%B3%95%E4%BB%98%E5%8D%B7%E7%A7%AF%22%5D%0A%20%20Q%20--%3E%20V%5B%22%E7%82%B9%E5%80%BC%E4%BE%A7%EF%BC%9A%E4%B9%98%E6%B3%95%E9%80%90%E7%82%B9%E4%BE%BF%E5%AE%9C%E3%80%81%E5%8A%A0%E6%B3%95%E4%BB%98%E6%8F%92%E5%80%BC%22%5D%0A%20%20C%20--%3E%20F%7B%22%E8%8A%82%E7%82%B9%E7%AD%89%E8%B7%9D%E5%90%97%22%7D%0A%20%20V%20--%3E%20F%0A%20%20F%20--%3E%7C%22%E6%98%AF%22%7C%20O1%5B%22%E5%89%8D%E5%90%8E%E7%BC%80%E7%A7%AF%EF%BC%9A%E5%8D%95%E7%82%B9%E6%8F%92%E5%80%BC%20O(n)%22%5D%0A%20%20F%20--%3E%7C%22%E5%90%A6%22%7C%20O2%5B%22%E5%88%86%E6%B2%BB%E4%B9%98%E6%B3%95%EF%BC%9A%E5%AE%8C%E6%95%B4%E6%8F%92%E5%80%BC%20O(n%20log%20%E5%B9%B3%E6%96%B9%20n)%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=e('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>数值域里插值怕病态节点（等距大节点下高次振荡），竞赛场景几乎都走模素数——逆元用费马小定理现取。\\(k\\) 次多项式要 \\(k+1\\) 个点，少一个点留自由度，多给的点拿来验证而不是硬塞。分治版插值能替代 Newton 形式的手工差商，但常数更大。与下一课的衔接在「对称」：等价类计数的去重缺口，由 Burnside 的平均不动点来补。</p><p><span class="marginnote">常见误区：把「\\(n+1\\) 个点」读成「次数 \\(n+1\\)」。错在把点数当次数——\\(n+1\\) 个互异点钉死的是次数<strong>至多 \\(n\\)</strong> 的多项式；要唯一确定次数恰为 \\(k\\) 的多项式，给 \\(k+1\\) 个点。差一个自由度，外推就飘。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>\\(n+1\\) 个互异点唯一确定次数至多 \\(n\\) 的多项式，Lagrange 公式给出显式解。</li><li>单点插值 \\(O(n)\\)：整体连乘、逐项除一次式、按 \\(y_i\\) 加权。</li><li>等距点是计数利器，\\(\\sum i^k\\) 这类求和直接插回去。</li><li>任意节点完整插值走分治，\\(O(n\\log^2 n)\\)。</li><li>出处：J.-L. Lagrange, 1795；J. von zur Gathen 与 J. Gerhard, <em>Modern Computer Algebra</em>；cp-algorithms 的 Lagrange Interpolation 词条。</li></ul>',5))])}const F=i(p,[["render",d]]);export{D as __pageData,F as default};
